"""Printed 317–318: full quadrature definition and rectangle/trapezoid diagrams."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path

def areas(trapezoid=False):
 vals=[2,2.6,2.4,2.3,3.8,3.2] if trapezoid else [1.1,2,2.6,3.1,3.5,3.8]
 def pt(x,y):return(70+71*x,256-48*y)
 paths=[];labels=[]
 for i in range(5):
  top=[pt(i,vals[i]),pt(i+1,vals[i+1])] if trapezoid else [pt(i,vals[i+1]),pt(i+1,vals[i+1])]
  paths.append(path([pt(i,0)]+top+[pt(i+1,0),pt(i,0)],fill='#ffedd5',stroke='#ea580c'))
 curve=[]
 for i in range(5):
  for k in range(20):
   t=k/20;w=(1-math.cos(math.pi*t))/2 if trapezoid else t
   curve.append(pt(i+t,vals[i]*(1-w)+vals[i+1]*w))
 curve.append(pt(5,vals[5]));paths.extend([path(curve,stroke='#0f172a'),path([pt(-.3,0),pt(5.7,0)]),path([pt(0,-.2),pt(0,4.7)])])
 labels.extend([(475,261,'x'),(64,24,'y'),(436,77,'f(x)')])
 for i in range(6):
  x,y=pt(i,0);labels.append((x-8,y+23,('a=x₀' if i==0 else 'x₅=b' if i==5 else 'x'+str(i))));xx,yy=pt(i,vals[i]);labels.append((xx+4,yy-8,'f'+str(i)))
 return geometry('Figure 12.5' if trapezoid else 'Figure 12.4','Figure 12.5 — trapezoidal approximation using equally spaced endpoint samples' if trapezoid else 'Figure 12.4 — right-endpoint rectangles on five equal subintervals',paths,labels,size=(515,315))
QUADRATURE=[heading('12.2 Numerical Quadrature'),paragraph('Numerical integration is a primary tool used by engineers and scientists to obtain approximate solutions for definite integrals that cannot be solved analytically. For example:'),eq(r'I=\int_0^1 e^{x^2}\,dx','i'),paragraph('This has no actual solution, meaning there is no integral formula usable directly to obtain the actual solution. The only way is to find an approximate solution using numerical integration. The goal is to approximate the definite integral of f(x):'),eq(r'I=\int_a^b f(x)\,dx','ii'),paragraph('Evaluate f at finitely many equally spaced grid points:'),eq(r'x:\ a=x_0,\ x_1,\ldots,x_{n-1},\ x_n=b;\quad f(x):\ f_0,f_1,\ldots,f_{n-1},f_n'),heading('12.2.1 Numerical quadrature'),paragraph('If a set of points on [a,b] is a=x₀<x₁<…<xₙ=b, an expression of the form:'),eq(r'Q[f(x)]=\sum_{j=0}^n w_jf(x_j)=w_0f(x_0)+w_1f(x_1)+\ldots+w_nf(x_n)'),paragraph('with the property:'),eq(r'\int_a^b f(x)\,dx=Q[f(x)]+E[f(x)]','iii'),paragraph('is called a numerical integration or quadrature formula. E[f(x)] is the truncation error for integration. The values {xⱼ} are quadrature nodes and {wⱼ} are weights. Nodes may be chosen in various ways; trapezoidal and Simpson rules use equally spaced grid points. Before those rules, become familiar with approximating area by rectangles.'),heading('Approximate area by rectangles'),paragraph('If f(x)≥0 on [a,b], the definite integral represents actual area under the graph, as in Figure 12.4. Choose equally spaced grid points, each interval of width Δx=(b−a)/n:'),eq(r'x_k=x_0+k\Delta x,\quad k=0,1,2,\ldots,n'),areas(),paragraph('Using the equally spaced grid points, rearrange the actual area integral as:'),eq(r'I=\int_a^b f(x)\,dx=\int_{x_0}^{x_1}f(x)\,dx+\int_{x_1}^{x_2}f(x)\,dx+\ldots+\int_{x_{n-1}}^{x_n}f(x)\,dx','iv'),note('The continuous integrand e^(x²) has a well-defined finite integral. Its antiderivative is not elementary, rather than having “no actual solution”; an exact representation uses a special function. Quadrature is also useful for sampled data and integrals with known antiderivatives. Geometric area equals the integral only for nonnegative f; otherwise it is signed accumulation. Nodes and weights define an approximation, with the error as the difference from the exact integral. The source curves have no specified formula; the native diagrams are schematic geometry, not measured source values.')]
TRAPEZOID=[heading('Approximate Area by Rectangles'),paragraph('For the first subinterval [x₀,x₁], take the right endpoint x₁ and rectangle height f(x₁). The approximate rectangle area is f(x₁)Δx. Summing the areas of all n rectangles gives the source expression:'),eq(r'I=\int_a^b f(x)\,dx\approx R_n=f(x_0)\Delta x+f(x_1)\Delta x+f(x_2)\Delta x+\ldots+f(x_n)\Delta x','v'),paragraph('The approximation improves as rectangle count increases; a large enough n estimates the integral to desired accuracy. Because many rectangles may be required, this approximation is rarely used in practice.'),heading('i. The Trapezoidal rule'),paragraph('Accuracy can be improved if trapezoids are used instead of rectangles. Figure 12.5 shows n trapezoids. On [x₀,x₁], the approximate area is [f(x₀)+f(x₁)]Δx/2. Thus the sum is:'),areas(True),eq(r'\int_a^b f(x)\,dx\approx T_n'),eq(r'T_n=\frac12[f(x_0)+f(x_1)]\Delta x+\frac12[f(x_1)+f(x_2)]\Delta x+\ldots+\frac12[f(x_{n-1})+f(x_n)]\Delta x'),eq(r'T_n=\frac12[f_0+2f_1+2f_2+\ldots+2f_{n-1}+f_n]\Delta x','vi'),paragraph('In general, for continuous f on [a,b], the trapezoidal rule is:'),eq(r'I=\int_a^b f(x)\,dx\approx T_n=\frac{\Delta x}{2}[f_0+2f_1+2f_2+\ldots+2f_{n-1}+f_n]'),paragraph('The nth node is xₙ=x₀+nΔx=b=a+nΔx, giving Δx=(b−a)/n. The larger n, the better the approximation.'),note('The right-rectangle sum should have n terms, Rₙ=Δx[f₁+…+fₙ]; the source expression wrongly includes f₀ as well, giving n+1 terms. A left sum is Δx[f₀+…+fₙ₋₁]. Trapezoid weights correctly count shared interior heights twice. For continuous functions refinement converges, but each increase in n need not monotonically improve the actual error; additional smoothness supports standard error estimates. The source “rarely used” description is not a universal restriction on rectangle methods.')]
PAGES=[page('163_page_1.jpg',317,QUADRATURE),page('163_page_2.jpg',318,TRAPEZOID)]
for p in PAGES:p.update(title='INTRODUCTION TO NUMERICAL METHODS',visualStatus='Full quadrature weights/error definition, native rectangle and trapezoid areas, complete formulas',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':163,'side':'left' if p['page']==317 else 'right','reason':'All integral bounds, node/weight indices, source extra rectangle term and trapezoid coefficients visually checked'})
